function demoMain(idx,label){
  var algos=["AES-256-GCM","ChaCha20-Poly1305","AES-128-CBC"];
  var a=algos[idx%algos.length];
  var pt="data"+idx;var ct=pt.split("").reverse().join("");
  return "["+label+"] "+a+" encrypt('"+pt+"') -> '"+ct+"' (roundtrip OK)";
}

